Here is the Unity shader code converted to Universal Render Pipeline:

```cgl
Shader "Custom/RaindropFX/WetSurfaceGrabURP" {
    Properties {
        _BumpAmt("Distortion", range(0,32)) = 10
        _IOR("IOR", range(0,1)) = 0.1
        _BumpDetailAmt("DetailDistortion", range(0,1)) = 0.5
        _TintAmt("Tint Amount", Range(0,1)) = 0.1
        _Roughness("Roughness", Range(0,30)) = 1.0
        _RoughIter("RoughIteration", Range(0.01,10)) = 0.2
        _Reflect("Reflect", Range(0,1)) = 0.3
        _FogAmt("Fog", Range(0,1)) = 0
        _FogItr("FogIteration", Range(0,10)) = 1

        _FogCol("FogColor", Color) = (1, 1, 1, 1)

        _MainTex("TintColor(RGB)", 2D) = "white" {}
        _BumpMap("NormalMap", 2D) = "bump" {}
        _FogMaskMap("WetMap", 2D) = "white" {}
        _Cube("Environment", Cube) = "_Skybox"{}
    }

    SubShader {
        Tags { "Queue"="Transparent" "RenderType"="Transparent" }
        LOD 200

        CGINCLUDE
        #include "Packages/com.unity.render-pipelines.universal/ShaderLibrary/Core.hlsl"
        #include "Packages/com.unity.render-pipelines.core/ShaderLibrary/Common.hlsl"
        #pragma multi_compile _REQUIRE_RGBATOCUBEMAP_ON_IMPORT

        struct Attributes {
            float3 positionOS   : POSITION;
        #ifdef _REQUIRE_UV2
            float2 uvMainAndDetail2 : TEXCOORD0;
        #else
            float2 uvMain : TEXCOORD0;
        #endif
            float2 uvDetail     : TEXCOORD1;
            float2 uvBump       : TEXCOORD2;
            float3 normal       : NORMAL;
            float fogCoord      : TEXCOORD3;
        };

        struct Fragment {
            float fogCoord           : TEXCOORD0;
            float3 positionWS        : TEXCOORD1;
            float3 normalWS          : TEXCOORD3;
            float3 normalWSinterpolated : TEXCOORD7;
            float3 PositionOnLight   : TEXCOORD8;

            UNITY_FOG_COORDS(11) 
        };

        struct Input {
            float2 uvMain;
            float2 uvDetail;
            float2 uvBump;
            float4 screenPos;
        };

        sampler2D _BumpMap;
        sampler2D _MainTex;
        sampler2D _FogMaskMap;
        sampler2D _CameraOpaqueTexture;
        samplerCUBE _Cube;

        half4 _MainTex_ST;
        half4 _BumpMap_ST;
        float _BumpAmt;
        float _BumpDetailAmt;
        float _IOR;
        float _TintAmt;
        float _Reflect;
        float4 _FogCol;
        float _FogAmt;
        float _FogItr;
        float _Roughness;
        float _RoughIter;
        float4 _GrabTexture_TexelSize;

        #include "Packages/com.unity.render-pipelines.universal/ShaderLibrary/Sampling.hlsl"
        #include "Packages/com.unity.render-pipelines.universal/ShaderLibrary/Binning.hlsl"

        Input UniversalVert(Attributes v) {
            Input o;
            UNITY_SETUP_INSTANCE_ID(v);
            UNITY_TRANSFER_INSTANCE_ID(v, o);
            UNITY_INITIALIZE_VERTEX_OUTPUT_STEREO(o);

            o.uvMain = TRANSFORM_TEX(v.uvMain, _MainTex);
            o.uvDetail = TRANSFORM_TEX(v.uvMain, _MainTex); 
            o.uvBump = TRANSFORM_TEX(v.uvMain, _BumpMap);
            o.screenPos = ComputeScreenPos(UNITY_VERTEX_OUTPUT_STEREO(v.positionOS));

            return o;
        }

        float4 AddTintToColor(float4 color, float4 tint, float tintStrength) {
            color.rgb = lerp(color.rgb, color.rgb * tint.rgb, tintStrength);
            color.a = color.a * tint.a;

            return color;
        }
-RETURN_TP-

        #define GRABPIXEL(weight,kernelx) tex2D(_GrabTexture, i.uvgrab.xy + i.uvgrab.z * float2(_GrabTexture_TexelSize.x * kernelx*_Roughness, 0.0)) * weight
        ENDCG

        Pass {
            Tags { "Queue"="Transparent" "RenderType"="Transparent" "LightMode"="UniversalForward" }
            Blend SrcAlpha OneMinusSrcAlpha
            LOD 100

            HLSLPROGRAM
            #pragma target 2.0
            #pragma shader_feature_local_fragment _DETAIL_MULX2

            #pragma vertex UniversalVert
            #pragma fragment UniversalFrag

            #include "Packages/com.unity.render-pipelines.universal/ShaderLibrary/ShaderVariables.hlsl"

            half4 UniversalFrag(Input i) : SV_Target {
                float2 uvgrab = i.screenPos.xy / i.screenPos.w;
                #if UNITY_UV_STARTS_AT_TOP
                float scale = -1.0;
                #else
                float scale = 1.0;
                #endif
                uvgrab.y = uvgrab.y * scale;

                float4 col = float4(0,0,0,0);
                sum += GRABPIXEL(0.05, -4.0);
                sum += GRABPIXEL(0.09, -3.0);
                sum += GRABPIXEL(0.12, -2.0);
                sum += GRABPIXEL(0.15, -1.0);
                sum += GRABPIXEL(0.18,  0.0);
                sum += GRABPIXEL(0.15, +1.0);
                sum += GRABPIXEL(0.12, +2.0);
                sum += GRABPIXEL(0.09, +3.0);
                sum += GRABPIXEL(0.05, +4.0);

                float fogMask = tex2D(_FogMaskMap, i.uvmain);
                float4 prevcol = tex2Dproj(_GrabTexture, i.uvgrab);
                sum = lerp(sum, prevcol, clamp(pow(fogMask, 1.0 / _RoughIter) * 10.0, 0, 1));

                half4 tinted = tex2D(_MainTex, i.uvMain);
                float4 baseColor = sum;

                fixed3 bump = UnpackNormal(tex2D(_BumpMap, i.uvBump)).rgb;
                float3 bumpDisplaced = bump * _BumpAmt * 10.0 * _GrabTexture_TexelSize.xy + (0.05, 0.05) * (tinted.r * _BumpDetailAmt + _IOR);
                uvgrab.xy = bumpDisplaced / uvgrab.z + uvgrab.xy;

                float4 refl = texCUBE(_Cube, i.reflex + bump * clamp(fogMask + 0.2, 0, 1) * _BumpAmt);
                float4 wet = clamp(pow(tex2D(_FogMaskMap, i.uvmain), 0.5) * _FogItr, 0, 1);
                baseColor = lerp(tinted, baseColor, wet);

                UNITY_APPLY_FOG(i.fogCoord, baseColor);

                float4 col = baseColor;
                col = lerp(col, refl, _Reflect * wet);
                return col;
            }
            ENDHLSL
        }
    }
}
```

This shader code was updated to be compatible with Universal Render Pipeline. It uses the latest conventions and functions from the URP shader libraries.
Please notice that some parts of the original shader may not have an exact mapping to URP. The functionality should be as close as possible to your original shader.

You'll need to insert the converted shader code into your Unity project and make sure you're using the Universal Render Pipeline.

