import starcraft_ai_lib as sc2
from sc2.helpers import distance, evaluate_path, predict_enemy_behavior

class StarCraftAI:

    def __init__(self):
        self.groups = []
        self.should_attack = False

    def main(self):
        while True:
            self.update_groups()
            self.check_attack_condition()
            self.decide_next_move()
            self.execute_plan()

    def update_groups(self):
        for character in sc2.all_characters():
            if character not in self.groups:
                self.assign_to_group(character)

    def assign_to_group(self, character):
        suitable_group = find_suitable_group(character)
        if suitable_group is None:
            suitable_group = create_new_group(character)
        self.groups.append(suitable_group)

    def check_attack_condition(self):
        army_strength = self.calculate_army_strength()
        resources = sc2.resources()

        if army_strength > THRESHOLD or unexpected_enemy_weakness():
            self.should_attack = True

    def decide_next_move(self):
        best_path = None

        for path in sc2.all_possible_paths():
            path_score = evaluate_path(path)
            path_prediction = predict_enemy_behavior(path)

            if best_path is None or (path_score, path_prediction) > (best_score, best_prediction):
                best_path, best_score, best_prediction = path, path_score, path_prediction

        self.next_move = best_path

    def execute_plan(self):
        if self.should_attack:
            sc2.attack(self.next_move)
        else:
            sc2.gather_resources(self.next_move)

if __name__ == "__main__":
    ai = StarCraftAI()
    ai.main()
