G3_c = d2c(G3);
%% Write the state space equations of the closed-loop system.
[A, B, C, D] = ssdata(G3_c); % Obtain state-space matrices from continuous-time model
n = size(A, 1);
m = size(B, 2);
X = sdpvar(n);
Y = sdpvar(m, n, 'full');
G =[-B*Y; C];
Gamma = null(C);
[A3tilde, B3tilde, C3tilde, D3tilde] = ssdata(Gamma'*G3_c*Gamma);
GammaBar = [Gamma, zeros(n, m); zeros(m, n), eye(m)];
%% Schur lemma to obtain LMI
lmi = [[A*Gamma*Gamma'+Gamma*Gamma'*A'-Gamma*G*Y'-Gamma*Y*G', A*X-B*Y; (A*X-B*Y)', A+Y'*B']];
lmi=[lmi, X>=1e-5*eye(n)];
Objective = trace(C3tilde'*C3tilde*X); % objective function
ops = sdpsettings('solver','sedumi'); % change to mosek
