Future<List<Uint8List>> sliceImage(File imageFile) async {
  List<Uint8List> imageSlices = [];

  // Read the image file and decode it into an image object
  Uint8List imageData = await imageFile.readAsBytes();
  Image image = decodeImage(imageData);

  // Calculate the center coordinates and the dimensions of each slice
  int centerX = image.width ~/ 2;
  int centerY = image.height ~/ 2;

  // Create slices
  Image topLeft = copyCrop(image, 0, 0, centerX, centerY);
  Image topRight = copyCrop(image, centerX, 0, centerX, centerY);
  Image bottomLeft = copyCrop(image, 0, centerY, centerX, centerY);
  Image bottomRight = copyCrop(image, centerX, centerY, centerX, centerY);

  // Encode each slice back to bytes
  imageSlices..add(encodePng(topLeft))
          ...add(encodePng(topRight))
          ...add(encodePng(bottomLeft))
          ...add(encodePng(bottomRight));

  return imageSlices;
}
```

