```cpp
#include <iostream>
#include <string>
#include <vector>
#include <algorithm>

// Base class for museum exhibits
class Exhibit {
public:
    Exhibit(const std::string& name) : name_(name) {}
    virtual ~Exhibit() = default;

    const std::string& getName() const { return name_; }

    // Polymorphic method
    virtual void display() const = 0;

private:
    std::string name_;
};

// Derived class for painting exhibits
class Painting : public Exhibit
{
public:
    Painting(const std::string& name, const std::string& artist) : Exhibit(name), artist_(artist) {}

    const std::string& getArtist() const { return artist_; }

    void display() const override {
        std::cout << "Displaying painting: " << getName() << " by " << getArtist() << std::endl;
    }

private:
    std::string artist_;
};

// Derived class for sculpture exhibits
class Sculpture : public Exhibit
{
public:
    Sculpture(const std::string& name, const std::string& material)
        : Exhibit(name), material_(material) {}

    const std::string& getMaterial() const { return material_; }

    void display() const override {
        std::cout << "Displaying sculpture: " << getName() << " made of " << getMaterial() << std::endl;
    }

private:
    std::string material_;
};

// 3 more derived classes
class Photography : public Exhibit
{
public:
    Photography(const std::string& name, const std::string& photographer)
        : Exhibit(name), photographer_(photographer) {}

    const std::string& getPhotographer() const { return photographer_; }

    void display() const override {
        std::cout << "Displaying photograph: " << getName() << " by " << getPhotographer() << std::endl;
    }

private:
    std::string photographer_;
};

class Artifact : public Exhibit
{
public:
    Artifact(const std::string& name, const std::string& origin)
        : Exhibit(name), origin_(origin) {}

    const std::string& getOrigin() const { return origin_; }

    void display() const override {
        std::cout << "Displaying artifact: " << getName() << " from " << getOrigin() << std::endl;
    }

private:
    std::string origin_;
};

class Fossil : public Exhibit
{
public:
    Fossil(const std::string& name, const std::string& species)
        : Exhibit(name), species_(species) {}

    const std::string& getSpecies() const { return species_; }

    void display() const override {
        std::cout << "Displaying fossil: " << getName() << " of " << getSpecies() << std::endl;
    }

private:
    std::string species_;
};

int main() {
    // Create a vector of exhibit pointers
    std::vector<Exhibit*> exhibits;

    // Add some exhibits to the vector
    exhibits.push_back(new Painting("The Starry Night", "Vincent van Gogh"));
    exhibits.push_back(new Sculpture("David", "Marble"));
    exhibits.push_back(new Painting("The Persistence of Memory", "Salvador Dali"));
    exhibits.push_back(new Photography("Moonrise", "Ansel Adams"));
    exhibits.push_back(new Artifact("Rosetta Stone", "Egypt"));
    exhibits.push_back(new Fossil("Tyrannosaurus Rex", "T-Rex"));

    // Display each exhibit
    for (const auto& exhibit : exhibits) {
        exhibit->display();
    }

    // Delete exhibits
    for (const auto& exhibit : exhibits) {
        delete exhibit;
    }

    return 0;
}
```

