public static Vector2 velocityToPosition(Body body, Vector2 targetPosition, float maxSpeed) {
    Vector2 position = body.getPosition();
    Vector2 targetDirection = targetPosition.cpy().sub(position);
    Vector2 currentVelocity = body.getLinearVelocity();

    // the acceleration factor can be adjusted for faster movement
    float accelerationFactor = 2.0f;

    Vector2 desiredVelocity = targetDirection.nor().scl(maxSpeed);
    Vector2 velocityChange = desiredVelocity.sub(currentVelocity).scl(accelerationFactor);
    float deltaTime = Gdx.graphics.getDeltaTime();

    // calculate the new velocity
    Vector2 newVelocity = currentVelocity.add(velocityChange.scl(deltaTime));

    // check if the newVelocity would overshoot the target
    float overshootTime = newVelocity.len() / velocityChange.len();
    if (overshootTime < deltaTime) {
        // the new velocity will overshoot the target, so we set the velocity to reach the target exactly
        newVelocity = targetDirection.scl(1 / deltaTime);
    }

    return newVelocity;
}
