```java
import java.io.*;
import java.net.*;

public class PA14A_Server {
    public static void main(String[] args) {
        int port = 7777;

        try {
            // Create a server socket
            ServerSocket serverSocket = new ServerSocket(port);
            System.out.println("Server is running on port: " + port);

            while (true) {
                // Listen for a client connection
                Socket socket = serverSocket.accept();

                // Create input and output streams
                DataInputStream input = new DataInputStream(socket.getInputStream());
                DataOutputStream output = new DataOutputStream(socket.getOutputStream());

                // Receive loan information from client
                double annualInterestRate = input.readDouble();
                int numberOfYears = input.readInt();
                double loanAmount = input.readDouble();

                // Calculate monthly and total payments
                double monthlyInterestRate = annualInterestRate / 1200;
                double monthlyPayment = loanAmount * monthlyInterestRate / (1 -
                        (1 / Math.pow(1 + monthlyInterestRate, numberOfYears * 12)));
                double totalPayment = monthlyPayment * numberOfYears * 12;

                // Send monthly and total payments back to the client
                output.writeDouble(monthlyPayment);
                output.writeDouble(totalPayment);

                System.out.println("Loan information received: ");
                System.out.println("\tAnnual Interest Rate: " + annualInterestRate);
                System.out.println("\tNumber Of Years: " + numberOfYears);
                System.out.println("\tLoan Amount: " + loanAmount);
                System.out.println("Monthly and Total Payments sent back to the client.");
            }
        } catch (IOException ex) {
            System.err.println(ex);
        }
    }
}
```

