import java.io.*;
import java.net.*;
import java.util.Scanner;

public class PA14A_Client {
    public static void main(String[] args) {
        String host = "localhost";
        int port = 7777;

        try {
            // Connect to the server
            Socket socket = new Socket(host, port);

            // Create input and output streams
            DataInputStream input = new DataInputStream(socket.getInputStream());
            DataOutputStream output = new DataOutputStream(socket.getOutputStream());

            // Create a scanner for user input
            Scanner scanner = new Scanner(System.in);

            // Get loan information from the user
            System.out.print("Enter annual interest rate: ");
            double annualInterestRate = scanner.nextDouble();

            System.out.print("Enter number of years: ");
            int numberOfYears = scanner.nextInt();

            System.out.print("Enter loan amount: ");
            double loanAmount = scanner.nextDouble();

            // Send loan information to the server
            output.writeDouble(annualInterestRate);
            output.writeInt(numberOfYears);
            output.writeDouble(loanAmount);

            // Receive monthly and total payments from the server
            double monthlyPayment = input.readDouble();
            double totalPayment = input.readDouble();

            // Display the results
            System.out.println("Monthly Payment: " + monthlyPayment);
            System.out.println("Total Payment: " + totalPayment);

            // Close the connection
            socket.close();
        } catch (IOException ex) {
            System.err.println(ex);
        }
