const fs = require('fs');
const Papa = require('papaparse');

function parseCsvFile(filePath) {
  return new Promise((resolve, reject) => {
    const results = [];
    const stream = fs.createReadStream(filePath);

    Papa.parse(stream, {
      header: true,
      step: (result, parser) => {
        results.push(result.data);
      },
      complete: (result, file) => {
        resolve(results);
      },
      error: (error) => {
        reject(error);
      },
    });
  });
}

module.exports = {
