async function addWatermark(originalImagePath, watermarkPath) {
  // Get original image dimensions
  const {width, height} = await sharp(originalImagePath).metadata();

  // Choose appropriate watermark size (use your own logic)
  const watermarkSize = chooseProperWatermarkSize(width, height);

