    getImageColorAtPosition(originalImagePath, width - 1, 0, 1, 1), // top right
    getImageColorAtPosition(originalImagePath, 0, height - 1, 1, 1), // bottom left
    getImageColorAtPosition(originalImagePath, width - 1, height - 1, 1, 1), // bottom right
